    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        words = list(wordList)
        used = [False] * len(words)
        queue = [(beginWord, 1)]
        head = 0
        while head < len(queue):
            word, step = queue[head]
            head += 1
            if word == endWord:
                return step
            for k in range(len(words)):
                if used[k]:
                    continue
                nxt = words[k]
                if len(nxt) != len(word):
                    continue
                diff = 0
                for a, b in zip(word, nxt):
                    if a != b:
                        diff += 1
                        if diff > 1:
                            break
                if diff == 1:
                    used[k] = True
                    queue.append((nxt, step + 1))
        return 0

